    title: forecast.notices?.[0] ?? forecast.summary,
    severity: weatherRiskToSeverity(forecast.status, forecast.riskLevel),
    startsAt: forecast.fetchedAt,
    source: "Open-Meteo",
    status: weatherStatusToLoadingStatus(forecast.status),
  },
];

