  const budgetKrw = typeof value === "number" ? value : Number(value);

  return Number.isFinite(budgetKrw) && budgetKrw > 0 ? Math.round(budgetKrw) : undefined;
};

const createPlacesByDayRecord = (days: GeneratedItineraryDay[]) =>
