  const normalizedCountry = country?.trim();

  if (!normalizedCountry) return "";
  if (!/^[A-Za-z]{2}$/.test(normalizedCountry)) return normalizedCountry;

  try {
    return koreanRegionNames.of(normalizedCountry.toUpperCase()) ?? normalizedCountry;
  } catch {
