export function canUseGoogleMapsCore(google: any): boolean {
  return (
    typeof google?.maps?.Map === "function" &&
    typeof google?.maps?.Geocoder === "function" &&
    typeof google?.maps?.LatLng === "function" &&
    typeof google?.maps?.event?.trigger === "function"
  );
}

