await write('src/components/diplolife/forms/LocationSearchInput.tsx', `
import { useState } from "react";

interface LocationSearchInputProps {
  defaultValue?: string;
  id?: string;
  label?: string;
  onResolvedLocation?: (location: ResolvedLocation | null) => void;
  placeholder?: string;
}

export interface ResolvedLocation {
  address: string;
  lat?: number;
  lng?: number;
}

const readCoordinate = (location: any, key: "lat" | "lng") => {
  const value = location?.[key];
  const coordinate = typeof value === "function" ? value.call(location) : value;
  return typeof coordinate === "number" && Number.isFinite(coordinate) ? coordinate : undefined;
};

export function createResolvedLocationFromGooglePlace(place: any, fallbackAddress: string): ResolvedLocation | null {
  const lat = readCoordinate(place?.geometry?.location, "lat");
  const lng = readCoordinate(place?.geometry?.location, "lng");
  const address = [place?.name, place?.formatted_address].filter(Boolean).join(", ") || fallbackAddress;
  if (!address && lat === undefined && lng === undefined) return null;
  return { address, ...(lat !== undefined ? { lat } : {}), ...(lng !== undefined ? { lng } : {}) };
}

export function createResolvedLocationFromGeocoderResult(result: any, fallbackAddress: string): ResolvedLocation | null {
  const lat = readCoordinate(result?.geometry?.location, "lat");
  const lng = readCoordinate(result?.geometry?.location, "lng");
  const address = result?.formatted_address || fallbackAddress;
  if (!address && lat === undefined && lng === undefined) return null;
  return { address, ...(lat !== undefined ? { lat } : {}), ...(lng !== undefined ? { lng } : {}) };
}

export function canUseGooglePlacesAutocomplete(google: any): boolean {
  return typeof google?.maps?.places?.Autocomplete === "function";
}

export function canUseGoogleMapsCore(google: any): boolean {
  return typeof google?.maps?.Map === "function" && typeof google?.maps?.Geocoder === "function" && typeof google?.maps?.LatLng === "function" && typeof google?.maps?.event?.trigger === "function";
}

export function createGoogleMapsScriptUrl(apiKey: string, callbackName: string): string {
  const params = new URLSearchParams({ key: apiKey, libraries: "places", callback: callbackName, loading: "async" });
  return `https://maps.googleapis.com/maps/api/js?${params.toString()}`;
}

export function LocationSearchInput({ defaultValue = "", id, label = "Location", onResolvedLocation, placeholder = "Search location" }: LocationSearchInputProps) {
  const [value, setValue] = useState(defaultValue);
  return (
    <label className="block space-y-2" htmlFor={id}>
      <span className="text-sm font-semibold">{label}</span>
      <input
        id={id}
        type="text"
        value={value}
        placeholder={placeholder}
        onChange={(event) => {
          const next = event.target.value;
          setValue(next);
          onResolvedLocation?.(next ? { address: next } : null);
        }}
        className="h-11 w-full rounded-lg border border-border bg-background px-3 text-sm"
      />
    </label>
  );
}
`);

