await write('src/components/diplolife/cards/LocalPriceCard.tsx', `
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useDiploLifeStore, type BudgetFitLevel } from "@/lib/diplolife/state";

export interface CountryCostFallbackRow {
  category: string;
  amount: number;
  currency: string;
  fitLevel: BudgetFitLevel;
}

export function createCountryCostFallbackRows(input: { monthlyCost?: number | null; currency?: string | null } | null | undefined): CountryCostFallbackRow[] {
  const monthlyCost = Number(input?.monthlyCost ?? 0);
  const currency = input?.currency || "USD";
  const base = Number.isFinite(monthlyCost) && monthlyCost > 0 ? monthlyCost / 30 : 0;
  return [
    { category: "Food", amount: Math.round(base * 0.35), currency, fitLevel: "moderate" },
    { category: "Transport", amount: Math.round(base * 0.15), currency, fitLevel: "moderate" },
    { category: "Activity", amount: Math.round(base * 0.2), currency, fitLevel: "moderate" },
  ];
}

export function LocalPriceCard() {
  const costInsight = useDiploLifeStore((state) => state.costInsight);
  const rows = createCountryCostFallbackRows({ monthlyCost: costInsight.analysis?.monthlyCost, currency: costInsight.analysis?.currency });
  return (
    <Card>
      <CardHeader>
        <CardTitle>Local prices</CardTitle>
      </CardHeader>
      <CardContent className="space-y-2">
        {rows.map((row) => (
          <div key={row.category} className="flex justify-between text-sm">
            <span>{row.category}</span>
            <span>{row.amount.toLocaleString()} {row.currency}</span>
          </div>
        ))}
      </CardContent>
    </Card>
  );
}
`);

